const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${{file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h5"/>',folder:'<path d="M3 5h7l2 3h9v12H3z"/>',plus:'<path d="M12 5v14M5 12h14"/>',send:'<path d="M12 19V5m-6 6 6-6 6 6"/>',book:'<path d="M3 5h6l3 2 3-2h6v15h-6l-3 2-3-2H3zM12 7v15"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'}[name]||''}</svg>`;
function messageText(v){return esc(v).split('\n').map(line=>line.replace(/^###? (.+)$/,'<strong>$1</strong>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')).join('\n');}
export function renderFrame(s,body,tutor){
  const {pages,page,materials,busy,importBusy,importLabel,runtime,hasNewMaterials}=s;
  const disabled=busy||importBusy?'disabled':'';
  return `<div class="studio"><header class="app-header"><a class="brand" href="#overview">${icon('book')}<strong>知序</strong><span>Learnmore</span></a><div class="header-tools"><button class="runtime-status" data-action="refresh-runtime"><i class="status-dot ${runtime.loggedIn?'connected':''}"></i>${runtime.mode==='checking'?'连接中':runtime.loggedIn?'本地 Codex':'未连接 Codex'}</button><details class="more-menu"><summary aria-label="更多功能">···</summary><div><button data-action="import">管理材料 / 项目对话</button><button data-action="search">搜索知识点　Ctrl K</button><button data-action="download-course">导出完整阅读版</button><button data-action="restore-demo">机器学习示例</button><button data-action="reset-progress">重置本课进度</button></div></details></div></header>
  <section class="material-bar" id="material-dropzone" aria-label="拖入学习材料"><div class="material-intro"><span class="material-icon">${icon('file')}</span><div><strong>${importBusy?esc(importLabel):materials.length?`已选 ${materials.length} 份材料`:'拖入文件，开始学明白'}</strong><p>${importBusy?'正在本机提取文字…':materials.length?(hasNewMaterials?'可以直接提问，或整理成一门简明课程。':'这些材料会随问题一起交给老师。'):'PDF、Word、PPT、文本 · 也可以选择整个文件夹'}</p></div></div><div class="material-actions"><button class="btn btn-light" data-action="pick-files" ${disabled}>${icon('plus')}选择文件</button><button class="btn btn-light" data-action="pick-folder" ${disabled}>${icon('folder')}选择文件夹</button>${materials.length?`<button class="btn btn-primary" data-action="generate-course" ${disabled}>整理课程</button>`:''}<button class="text-button" data-action="import">${materials.length?'管理':'粘贴文本'}</button></div>${materials.length?`<div class="material-chips">${materials.slice(0,4).map((m,i)=>`<span class="file-chip"><button data-preview-material="${i}" title="${esc(m.name)}">${icon('file')}${esc(m.name.split(/[\\/]/).at(-1))}</button><button data-remove-material="${i}" aria-label="移除 ${esc(m.name)}" ${disabled}>${icon('close')}</button></span>`).join('')}${materials.length>4?`<button class="text-button" data-action="import">另 ${materials.length-4} 份</button>`:''}</div>`:''}</section>
  ${s.materialNotice?`<div class="import-notice" role="status">${esc(s.materialNotice)}</div>`:''}<nav class="learning-tabs" aria-label="学习方式">${Object.entries(pages).filter(([id])=>id!=='sources').map(([id,label])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${label}</button>`).join('')}<button class="ask-jump" data-action="focus-chat">问老师 ↓</button></nav><main id="main-content" class="learn-area">${body}</main>${tutor}<footer class="app-footer">在本机整理与阅读 · 仅在提问或生成时调用 Codex</footer></div>`;
}
export function overviewView({data,materials,learning,hasNewMaterials}){
  if(hasNewMaterials)return `<section class="overview"><span class="context-label">材料已准备好</span><h1>先弄明白重点，再按需深入。</h1><p>在下方直接问这 ${materials.length} 份材料，或点击“整理课程”，生成概览、课程、名词公式和分级练习，再选择喜欢的故事风格。</p><div class="overview-actions"><button class="btn btn-primary" data-ask="请根据已选材料，用通俗语言先讲清楚：主要在讲什么、最重要的三个知识点、它们之间的关系。先简明概览，遇到公式解释符号和用途。">先给我讲明白</button><button class="btn btn-light" data-action="generate-course">整理成课程</button></div></section>`;
  return `<section class="overview"><div class="overview-title"><span class="context-label">${data.id==='machine-learning'?'机器学习示例 · 可先体验，也可导入自己的材料':'我的学习内容'}</span><button class="text-button" data-action="download-course">导出阅读版 ↗</button></div><h1>${esc(data.title)}</h1><p>${esc(data.summary)}</p><div class="knowledge-path">${data.chapters.map((c,i)=>`<button data-chapter="${i}"><span>${learning.read.includes(c.id)?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${esc(c.title)}</strong><small>${esc(c.kicker)}</small></div><b>↗</b></button>`).join('')}</div></section>`;
}
export function tutorView({chat,draft,busy,materials,page,pages}){
  return `<section class="conversation" id="conversation" aria-label="学习对话"><div class="conversation-heading"><strong>和老师聊聊</strong><span>${materials.length?`${materials.length} 份材料 · `:''}${esc(pages[page])}上下文</span>${chat.length?'<button class="text-button" data-action="clear-chat">清空对话</button>':''}</div><div class="chat-history" id="chat-history" aria-live="polite">${chat.length?chat.map(m=>`<article class="chat-message ${esc(m.role)}"><div class="message-role">${m.role==='user'?'你':m.role==='error'?'连接提示':'知序 · Codex'}</div><div class="message-body">${messageText(m.text)}</div></article>`).join(''):'<p class="chat-empty">哪里不懂，直接问。老师会结合你的材料和当前阅读内容解释。</p>'}${busy?`<div class="working"><span class="spinner"></span><span id="job-status">${{chat:'正在思考',course:'正在整理课程',story:'正在生成故事'}[busy.type]} · ${busy.elapsed||0} 秒</span><button class="text-button" data-action="cancel-job" ${!busy.id?'disabled':''}>停止</button></div>`:''}</div><form class="chat-composer" id="chat-form"><textarea id="chat-input" rows="2" maxlength="4000" aria-label="向老师提问" placeholder="问一个问题，例如：这个公式为什么这样算？">${esc(draft)}</textarea><div class="composer-bottom"><div><button type="button" class="attach-button" data-action="pick-files" aria-label="添加学习文件" ${busy?'disabled':''}>${icon('plus')}</button><span>Enter 发送 · Shift + Enter 换行</span></div><button class="send" type="submit" aria-label="发送问题" ${busy?'disabled':''}>${icon('send')}</button></div></form><div class="suggestions"><button data-ask="请用一个生活中的例子，把当前知识点讲明白。">通俗讲一遍</button><button data-ask="请解释当前知识点的公式符号、适用条件，并用具体数字带我算一遍。">带我算一遍</button><button data-ask="请针对当前材料的核心知识点，提出一个具体的问题问我，先不要给答案。">出一道题问我</button></div></section>`;
}
export function sourcesView({materials,sourcePreview,materialDraft,projectRoot,sessions,busy}){
  return `<div class="dialog-heading"><h2>学习材料</h2><button class="btn-icon" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="dialog-actions"><button class="btn btn-light" data-action="pick-files">${icon('plus')}选择文件</button><button class="btn btn-light" data-action="pick-folder">${icon('folder')}选择文件夹</button></div><div class="source-list">${materials.length?materials.map((m,i)=>`<div class="source-item"><button class="source-name" data-preview-material="${i}">${icon('file')}<span>${esc(m.name)}<small>${m.text.length.toLocaleString()} 字符 · ${esc(m.kind||'文本')}</small></span></button><button class="btn-icon" data-remove-material="${i}" aria-label="移除 ${esc(m.name)}" ${busy?'disabled':''}>${icon('close')}</button></div>`).join(''):'<p class="empty">还没有选择材料。</p>'}</div>${sourcePreview?`<details open><summary>查看正文</summary><pre class="source-preview">${esc(sourcePreview.slice(0,12000))}</pre></details>`:''}<details class="source-option"><summary>粘贴一段文字</summary><textarea id="material-text" aria-label="学习材料" placeholder="粘贴讨论、笔记或需要学习的内容…">${esc(materialDraft)}</textarea><button class="btn btn-primary" data-action="add-text">加入材料</button></details><details class="source-option"><summary>选取项目里的近期 Codex 对话</summary><label for="project-root">项目目录</label><input id="project-root" value="${esc(projectRoot)}"><div class="dialog-actions"><button class="btn btn-light" data-action="find-sessions">查找近期对话</button><button class="btn btn-light" data-action="read-project">读取项目文本</button></div>${sessions.map(s=>`<div class="source-item"><span>${esc(s.name)}</span><button class="text-button" data-session="${esc(s.id)}">加入</button></div>`).join('')}</details><p class="dialog-footnote">材料留在当前浏览器；提问或整理课程时，才通过本机 Codex 处理。文档只提取文字，不执行文件内容。</p>`;
}
